import{_ as t,o,c as a,a3 as i}from"./chunks/framework.BTQ4eCVb.js";const h=JSON.parse('{"title":"EloSync Mobile","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"EloSync Mobile | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/elosync-mobile"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"EloSync Mobile | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/elosync-mobile"}]]},"headers":[],"relativePath":"user-guide/elosync-mobile.md","filePath":"user-guide/elosync-mobile.md","lastUpdated":1787698014000}'),r={name:"user-guide/elosync-mobile.md"};function n(s,e,l,d,c,p){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="elosync-mobile" tabindex="-1">EloSync Mobile <a class="header-anchor" href="#elosync-mobile" aria-label="Permalink to &quot;EloSync Mobile&quot;">​</a></h1><p>Tenant workspace app for <strong>iOS</strong> and <strong>Android</strong>. Sign in with the same email and permissions as the web workspace — Central admin is not available on mobile.</p><h2 id="sign-in" tabindex="-1">Sign in <a class="header-anchor" href="#sign-in" aria-label="Permalink to &quot;Sign in&quot;">​</a></h2><ol><li>Open the EloSync app (development build or store release when available).</li><li>Enter your <strong>email</strong> and <strong>password</strong>.</li><li>Optional: workspace slug for branded login or if directed by your administrator.</li><li>Complete <strong>email verification</strong> if prompted.</li></ol><p>Forgot password requires your <strong>workspace</strong> slug or domain plus email (the mobile app is not tied to a workspace subdomain URL like the browser).</p><h2 id="what-s-on-mobile-today" tabindex="-1">What&#39;s on mobile today <a class="header-anchor" href="#what-s-on-mobile-today" aria-label="Permalink to &quot;What&#39;s on mobile today&quot;">​</a></h2><p>Mobile modules roll out <strong>PR-by-PR</strong>. The app home screen lists modules your role can access.</p><table tabindex="0"><thead><tr><th>Module</th><th>Mobile surface</th></tr></thead><tbody><tr><td><strong>Leads</strong></td><td>List, search, create, view, edit, delete (permission-gated)</td></tr><tr><td><strong>Tasks</strong></td><td>List, search, create, view, edit, delete, complete/reopen (permission-gated)</td></tr><tr><td><strong>Notifications</strong></td><td>In-app notification list, mark read</td></tr><tr><td><strong>Profile</strong></td><td>Account details, sign out</td></tr></tbody></table><p>Everything else remains on the web app until a mobile module PR ships. See the <a href="/getting-started/product-roadmap#elosync-mobile-tenant-app">product roadmap</a> and <a href="/developer-guide/mobile-app">developer mobile guide</a>.</p><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>Use the same API-backed data as the web — changes sync immediately.</li><li>Module and permission gates match the web app (installed Marketplace modules + Spatie permissions).</li><li>For full CRM workflows (import, board, integrations, Meta ads), use the web app.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/user-guide/leads-overview">Leads user guide</a></li><li><a href="/user-guide/tasks-overview">Tasks user guide</a></li><li><a href="/user-guide/tenant-application">Tenant application guide</a></li></ul>',13)])])}const u=t(r,[["render",n]]);export{h as __pageData,u as default};
